insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1517','6-76',1517,'犬','quǎn','Chó, cẩu','他养了一只可爱的犬。','Tā yǎng le yī zhǐ kě''ài de quǎn.','Anh ấy nuôi một con chó dễ thương.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1518','6-76',1518,'缺口','quēkǒu','Chỗ hổng, khe hở','墙上有一个缺口。','Qiáng shàng yǒu yī gè quēkǒu.','Trên tường có một lỗ hổng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1519','6-76',1519,'缺席','quēxí','Vắng mặt, không tham dự','他因病缺席了会议。','Tā yīn bìng quēxí le huìyì.','Anh ấy vắng mặt trong cuộc họp vì bệnh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1520','6-76',1520,'缺陷','quēxiàn','Khiếm khuyết, khuyết điểm','这个机器有一些缺陷。','Zhège jīqì yǒu yīxiē quēxiàn.','Cái máy này có một số khuyết điểm.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1521','6-77',1521,'瘸','qué','Khập khiễng, què','他摔倒了，腿瘸了。','Tā shuāi dǎo le, tuǐ quē le.','Anh ấy bị ngã, và chân bị què.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1522','6-77',1522,'确保','quèbǎo','Đảm bảo, bảo đảm','我们必须确保安全。','Wǒmen bìxū quèbǎo ānquán.','Chúng ta phải đảm bảo an toàn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1523','6-77',1523,'确立','quèlì','Xác lập, thiết lập','我们确立了新的目标。','Wǒmen quèlì le xīn de mùbiāo.','Chúng ta đã thiết lập mục tiêu mới.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1524','6-77',1524,'确切','quèqiè','Chính xác, xác thực','他的话很确切。','Tā de huà hěn quèqiè.','Lời của anh ấy rất chính xác.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1525','6-77',1525,'确信','quèxìn','Tin chắc, tin tưởng','我确信他会成功。','Wǒ quèxìn tā huì chénggōng.','Tôi tin chắc rằng anh ấy sẽ thành công.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1526','6-77',1526,'群众','qúnzhòng','Quần chúng, nhân dân','群众对这个政策表示支持。','Qúnzhòng duì zhège zhèngcè biǎoshì zhīchí.','Quần chúng ủng hộ chính sách này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1527','6-77',1527,'染','rǎn','Nhuộm, tô điểm','他染上了坏习惯。','Tā rǎn shàng le huài xíguàn.','Anh ấy mắc phải thói quen xấu.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1528','6-77',1528,'让步','ràngbù','Nhượng bộ, lùi bước','他最终做出了让步。','Tā zuìzhōng zuò chū le ràngbù.','Cuối cùng, anh ấy đã nhượng bộ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1529','6-77',1529,'饶恕','ráoshù','Tha thứ, tha lỗi','请你饶恕我的错误。','Qǐng nǐ ráoshù wǒ de cuòwù.','Xin hãy tha thứ cho lỗi lầm của tôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1530','6-77',1530,'扰乱','rǎoluàn','Quấy rối, làm loạn','这个消息扰乱了秩序。','Zhège xiāoxi rǎoluàn le zhìxù.','Tin tức này đã làm rối loạn trật tự.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1531','6-77',1531,'惹祸','rěhuò','Gây họa, gây rắc rối','他的行为惹祸了。','Tā de xíngwéi rěhuò le.','Hành động của anh ấy đã gây ra rắc rối.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1532','6-77',1532,'热泪盈眶','rèlèiyíngkuàng','Nước mắt đầm đìa','听到这个消息，她热泪盈眶。','Tīngdào zhège xiāoxi, tā rèlèi yíngkuàng.','Nghe tin này, cô ấy rơi nước mắt xúc động.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1533','6-77',1533,'热门','rèmén','Phổ biến, thịnh hành','这个话题非常热门。','Zhège huàtí fēicháng rèmén.','Chủ đề này rất hot.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1534','6-77',1534,'仁慈','réncí','Nhân từ, nhân hậu','他是一个仁慈的人。','Tā shì yī gè réncí de rén.','Anh ấy là một người nhân từ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1535','6-77',1535,'人道','réndào','Nhân đạo','他们提倡人道待遇。','Tāmen tíchàng réndào dàiyù.','Họ khuyến khích đối xử nhân đạo.');
