insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1537','6-77',1537,'人工','réngōng','Nhân công, lao động','这种技术需要人工操作。','Zhè zhǒng jìshù xūyào réngōng cāozuò.','Công nghệ này cần thao tác bằng tay.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1538','6-77',1538,'人家','rénjiā','Nhà cửa, gia đình','人家都说他很聪明。','Rénjiā dōu shuō tā hěn cōngmíng.','Người ta đều nói anh ấy rất thông minh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1539','6-77',1539,'人间','rénjiān','Nhân gian, thế gian','这是人间的天堂。','Zhè shì rénjiān de tiāntáng.','Đây là thiên đường trên trần gian.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1540','6-77',1540,'人士','rénshì','Nhân sĩ, người','这件事对我们有很大的影响。','Zhè jiàn shì duì wǒmen yǒu hěn dà de yǐngxiǎng.','Việc này có ảnh hưởng lớn đối với chúng tôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1541','6-78',1541,'人为','rénwéi','Do con người làm','他的成功不是偶然的，而是人为的。','Tā de chénggōng bù shì ǒurán de, ér shì rénwéi de.','Thành công của anh ấy không phải là ngẫu nhiên mà là do con người tạo ra.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1542','6-78',1542,'人性','rénxìng','Nhân tính, bản tính','人性有时是复杂的。','Rénxìng yǒushí shì fùzá de.','Tính cách con người đôi khi rất phức tạp.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1543','6-78',1543,'人质','rénzhì','Con tin, người bị bắt','绑架者要求人质的家人支付赎金。','Bǎngjià zhě yāoqiú rénzhì de jiārén zhīfù shújīn.','Những kẻ bắt cóc yêu cầu gia đình con tin trả tiền chuộc.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1544','6-78',1544,'忍耐','rěnnài','Nhẫn nại, chịu đựng','你必须学会忍耐。','Nǐ bìxū xuéhuì rěnnài.','Bạn phải học cách kiên nhẫn.');
