insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1548','6-78',1548,'任命','rènmìng','Bổ nhiệm, cử nhiệm','他被任命为公司经理。','Tā bèi rènmìng wèi gōngsī jīnglǐ.','Anh ấy được bổ nhiệm làm giám đốc công ty.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1549','6-78',1549,'任性','rènxìng','Tùy hứng, bướng bỉnh','她有点任性。','Tā yǒudiǎn rènxìng.','Cô ấy hơi bướng bỉnh.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1550','6-78',1550,'任意','rènyì','Tùy ý, tự do','你可以任意选择。','Nǐ kěyǐ rènyì xuǎnzé.','Bạn có thể chọn bất kỳ cái gì.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1551','6-78',1551,'任重道远','rènzhòngdàoyuǎn','Trách nhiệm nặng nề và đường dài','我们的任务任重道远。','Wǒmen de rènwù rènzhòngdàoyuǎn.','Nhiệm vụ của chúng ta còn rất nặng nề và xa xôi.');
