insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1568','6-79',1568,'散文','sǎnwén','Tản văn','他写了一篇散文。','Tā xiě le yī piān sǎnwén.','Anh ấy đã viết một bài tản văn.');
