insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('6-1570','6-79',1570,'丧失','sàngshī','Mất mát','他丧失了信心。','Tā sàngshī le xìnxīn.','Anh ấy đã mất niềm tin.');
